#!/bin/bash
# Fix Gradle files generated by flutter create.
# Flutter 3.47.5 generates build.gradle.kts (Kotlin DSL) with readWithUTF8()
# which was removed in Gradle 9.x. Replace with proper .kts files using
# AGP 9.x (required by Flutter 3.47.5 dependencies).
cd android

# Remove old Groovy files and Kotlin DSL files with readWithUTF8
rm -f build.gradle settings.gradle app/build.gradle
rm -f build.gradle.kts settings.gradle.kts app/build.gradle.kts

# Replace project-level build.gradle.kts with AGP 9.x compatible Kotlin DSL
cat > build.gradle.kts << 'EOF'
plugins {
    id("com.android.application") version "9.1.0" apply false
    id("org.jetbrains.kotlin.android") version "2.2.20" apply false
}

repositories {
    google()
    mavenCentral()
}
EOF

# Replace settings.gradle.kts with Groovy including pluginManagement for local Flutter plugin
# pluginManagement MUST be the first block in settings.gradle per Gradle docs
cat > settings.gradle << 'EOF'
pluginManagement {
    def localProperties = new Properties()
    def localPropertiesFile = new File("local.properties")
    if (localPropertiesFile.exists()) {
        localPropertiesFile.withReader('UTF-8') { reader ->
            localProperties.load(reader)
        }
    }
    def flutterRoot = localProperties.getProperty('flutter.sdk')
    if (flutterRoot == null) {
        throw new GradleException("Flutter SDK not found. Define location with flutter.sdk in the local.properties file.")
    }
    repositories {
        gradlePluginPortal()
        google()
        mavenCentral()
    }
    includeBuild "$flutterRoot/packages/flutter_tools/gradle"
}

include ':app'
EOF

# Replace app-level build.gradle with Kotlin DSL using Flutter Gradle Plugin declarative block
cat > app/build.gradle.kts << 'GRADLE_EOF'
plugins {
    id("com.android.application")
    id("org.jetbrains.kotlin.android")
    id("dev.flutter.flutter-gradle-plugin") version "3.47.5"
}

android {
    namespace = "com.helix.helix"
    compileSdk = 36

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_1_8
        targetCompatibility = JavaVersion.VERSION_1_8
    }
    kotlinOptions {
        jvmTarget = "1.8"
    }

    sourceSets {
        getByName("main").java.srcDirs("src/main/kotlin")
    }

    defaultConfig {
        applicationId = "com.helix.helix"
        minSdk = 21
        targetSdk = 36
        versionCode = localProperties["flutterVersionCode"]?.toInteger() ?: 1
        versionName = localProperties["flutterVersionName"] ?: "1.0.0"
    }
    buildTypes {
        release {
            signingConfig = signingConfigs.getByName("debug")
        }
    }
}

dependencies {
    implementation("org.jetbrains.kotlin:kotlin-stdlib-jdk8:2.2.20")
    implementation("androidx.core:core-ktx:+")
    implementation("androidx.annotation:annotation:+")
    implementation("androidx.lifecycle:lifecycle-runtime-ktx:+")
    implementation("androidx.activity:activity:+")
}

flutter {
    source = "../.."
}
GRADLE_EOF

echo "Gradle files fixed"
